model = bdroot;
df = get_param(model,'dirty');
try
    [D,uDelay,yDelay,xinit,Ts,sysname] = controllib.internal.blocks.lti.ltimaskData(gcb,sys,IC);
catch ME
    sysname = '???';
    throwAsCaller(MSLException(get_param(gcb,'handle'),ME.identifier,ME.message))
end
controllib.internal.blocks.lti.ltimaskUpdate(gcb,D,xinit,Ts,PadeOrder)
try
    % Attempt to modify locked library -> error
    set_param(model,'dirty',df)
end

